<?php require __DIR__.'/../bootstrap/app.php';login_required();if(user()['role']!=='customer')exit('Customer account required.');$db=Database::get();$q=$db->prepare('SELECT id,name FROM services WHERE id=? AND is_active=1');$q->execute([(int)($_GET['id']??0)]);$svc=$q->fetch();if(!$svc)exit('Service not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$db->prepare("INSERT INTO service_requests(customer_id,service_id,description,preferred_date,address,status) VALUES(?,?,?,?,?,'submitted')");$s->execute([user()['id'],$svc['id'],trim($_POST['description']),$_POST['date']?:null,trim($_POST['address'])]);notice('Service request submitted.');go('customer/index.php');}$title='Request service';require __DIR__.'/../app/Views/header.php';?><section class="section"><div class="container" style="max-width:700px"><form class="formbox" method="post"><h1><?=e($svc['name'])?></h1><?=csrf_field()?><label class="form-label">Describe what you need</label><textarea class="form-control mb-3" name="description" required rows="4"></textarea><label class="form-label">Preferred date</label><input class="form-control mb-3" type="date" name="date" min="<?=date('Y-m-d')?>"><label class="form-label">Service address</label><textarea class="form-control mb-3" name="address" required></textarea><button class="btn gold">Submit request</button></form></div></section><?php require __DIR__.'/../app/Views/footer.php';?>